import type { Meta, StoryObj } from "@storybook/react-vite";
import { expect, within } from "storybook/test";
import { Panel, PanelSection } from "../components/Panel/Panel";
import data from "./outlines.generated.json";
import { ShapeTiles, Shell } from "./pieces";

// The real outlines (M1 PR 5b) in the proposal's tiles, for Thor to judge:
// every continent's countries, and the countries that are hardest to draw
// small. The outlines are generated by the app's map build
// (apps/web/scripts/build-maps.ts, ADR 0020); outlines.generated.json is a copy
// for these stories, because the design system never imports from the app.

const names: Record<string, string> = {
	africa: "Africa",
	europe: "Europe",
	asia: "Asia",
	"north-america": "North America",
	"south-america": "South America",
	oceania: "Oceania",
};

const meta = {
	title: "Proposals/Outlines",
	parameters: { layout: "fullscreen" },
} satisfies Meta;
export default meta;

type Story = StoryObj<typeof meta>;

/** The world: the six continents, each merged from its countries, inside its map view's box. */
export const World: Story = {
	render: () => (
		<Shell current="World">
			<Panel title="The world" description="200 countries">
				<ShapeTiles
					items={data.continents.map(({ id, d, countries }) => ({
						name: names[id] ?? id,
						detail: `${countries.length} countries`,
						d,
					}))}
				/>
			</Panel>
		</Shell>
	),
	play: async ({ canvasElement }) => {
		await expect(within(canvasElement).getAllByRole("link")).toHaveLength(
			// Six tiles, and the seven chips of the stand-in shell.
			6 + 7,
		);
	},
};

const continent = (id: string): Story => {
	const { countries } = data.continents.find((each) => each.id === id) ?? {
		countries: [],
	};
	const regions = [...new Set(countries.map((country) => country.region))];
	return {
		render: () => (
			<Shell current={names[id] ?? id}>
				<Panel
					title={names[id] ?? id}
					description={`${countries.length} countries in ${regions.length} regions`}
				>
					{regions.map((region) => (
						<PanelSection key={region} title={region}>
							<ShapeTiles
								dense
								columns={4}
								items={countries.filter((country) => country.region === region)}
							/>
						</PanelSection>
					))}
				</Panel>
			</Shell>
		),
	};
};

export const Africa: Story = continent("africa");
export const Europe: Story = continent("europe");
export const Asia: Story = continent("asia");
export const NorthAmerica: Story = continent("north-america");
export const SouthAmerica: Story = continent("south-america");
export const Oceania: Story = continent("oceania");

/**
 * The hard cases, at the size a continent panel shows them. First as built:
 * each country is the land its name is on, the same land the map's country
 * view frames. Then the same countries with all their land, for comparison.
 */
export const HardCases: Story = {
	name: "Hard cases",
	render: () => (
		<Shell current="World">
			<Panel title="Hard cases" description="Small, scattered and very large">
				<PanelSection title="As built: the land the name is on">
					<ShapeTiles dense columns={4} items={data.hardCases} />
				</PanelSection>
				<PanelSection title="For comparison: all of the country's land">
					<ShapeTiles
						dense
						columns={4}
						items={data.hardCases.map(({ name, allLand }) => ({
							name,
							d: allLand,
						}))}
					/>
				</PanelSection>
			</Panel>
		</Shell>
	),
};
